@Test
void 이_장의_결론() {
    em.clear();
    List<String> names = queryFactory
            .select(member.username)
            .from(member)
            .where(member.age.between(10, 30))
            .orderBy(member.age.asc())
            .fetch();
    System.out.println(names);
}

